\subsection{Definitions and mathematical statement}
\paragraph{Shared notation.}$\mathbb N$, $\mathbb Z$, $\mathbb Q$, $\mathbb R$, and $\mathbb C$ denote the natural numbers, integers, rationals, reals, and complex numbers, respectively. All additional parameters and hypotheses are specified in the question.


\paragraph{Statement recorded in the supplied source.}
For $0\leq p<1$, origin-symmetric convex bodies $K,C\subseteq\mathbb R^n$, and every $\lambda\in[0,1]$, is

$$V\bigl((1-\lambda)K+_p\lambda C\bigr)\geq V(K)^{1-\lambda}V(C)^\lambda,$$

where $+_p$ denotes the $L_p$-linear combination?
\par\smallskip\textit{Formulation references:} \href{https://huggingface.co/datasets/ulamai/UnsolvedMath}{[S1]}, \href{https://doi.org/10.4171/owr/2018/54}{[S2]}.

\subsection{Short English statement}
For $0\leq p<1$, origin-symmetric convex bodies $K,C\subseteq\mathbb R^n$, and every $\lambda\in[0,1]$, is

$$V\bigl((1-\lambda)K+_p\lambda C\bigr)\geq V(K)^{1-\lambda}V(C)^\lambda,$$

where $+_p$ denotes the $L_p$-linear combination?

\subsection{Sources}
\begin{itemize}
\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 30004029 (OWR-16637-008). Catalogue attribution under CC BY 4.0.
\url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] Original problem formulation and mathematical context.
\url{https://doi.org/10.4171/owr/2018/54}.
\end{itemize}
\label{end:30004029}

